from datetime import datetime

stamps = ["2026-03-02T10:00", "2026-03-03T11:30", "2026-03-09T09:15", "2026-03-10T18:00", "2026-03-11T08:45", "2026-03-12T12:00", "2026-03-20T16:20"]
counts = {}
for text in stamps:
    week = datetime.fromisoformat(text).date().isocalendar()[1]
    counts[week] = counts.get(week, 0) + 1
for week in sorted(counts):
    print(f"Week {week}: {counts[week]}")
busiest = max(sorted(counts), key=lambda w: counts[w])
print(f"Busiest: Week {busiest}")
